options.helpers:
context.handlebars.registerHelper('detectionRows', rows => {
  const records = new Map();
  for (const row of Array.isArray(rows) ? rows : []) {
    let record;
    try { record = JSON.parse(row.Line || row.line || row.body || '{}'); } catch (_) { continue; }
    if (record.event !== 'crowdsec_alert' || !record.id) continue;
    const start = Date.parse(record.start_at), stop = Date.parse(record.stop_at);
    if (!Number.isFinite(start) || !Number.isFinite(stop)) continue;
    const params = new URLSearchParams({from: String(start - 30000), to: String(stop + 30000), refresh: '', 'var-alert': record.id, 'var-source': record.source_scope === 'Ip' ? record.source_ip : '__not_an_ip__'});
    records.set(record.id, {...record, stop, siteLabel: (record.sites || ['Unknown']).map(site => site === '_' ? 'Catch-all' : site).join(', '), timeLabel: new Date(stop).toLocaleString(), href: '/d/web-requests?' + params.toString()});
  }
  return Array.from(records.values()).sort((left, right) => right.stop - left.stop || left.id.localeCompare(right.id)).slice(0, 25);
});
